961: void cache_stats::print_stats(FILE *fout, unsigned long long streamID,
962:                               const char *cache_name) const {
963:   ///
964:   /// For a given CUDA stream, print out each non-zero cache statistic for every
965:   /// memory access type and status "cache_name" defaults to "Cache_stats" when
966:   /// no argument is provided, otherwise the provided name is used. The printed
967:   /// format is
968:   /// "<cache_name>[<request_type>][<request_status>] = <stat_value>"
969:   /// Specify streamID to be -1 to print every stream.
970: 
971:   std::vector<unsigned> total_access;
972:   std::string m_cache_name = cache_name;
973:   for (auto iter = m_stats.begin(); iter != m_stats.end(); ++iter) {
974:     unsigned long long streamid = iter->first;
975:     // when streamID is specified, skip stats for all other streams, otherwise,
976:     // print stats from all streams
977:     if ((streamID != -1) && (streamid != streamID)) continue;
978:     total_access.clear();
979:     total_access.resize(NUM_MEM_ACCESS_TYPE, 0);
980:     for (unsigned type = 0; type < NUM_MEM_ACCESS_TYPE; ++type) {
981:       for (unsigned status = 0; status < NUM_CACHE_REQUEST_STATUS; ++status) {
982:         fprintf(fout, "\t%s[%s][%s] = %llu\n", m_cache_name.c_str(),
983:                 mem_access_type_str((enum mem_access_type)type),
984:                 cache_request_status_str((enum cache_request_status)status),
985:                 m_stats.at(streamid)[type][status]);
986: 
987:         if (status != RESERVATION_FAIL && status != MSHR_HIT &&
988:             status != WRITE_ALLOCATED)
989:           // MSHR_HIT is a special type of SECTOR_MISS
990:           // so its already included in the SECTOR_MISS.
991:           // WRITE_ALLOCATE is a supplementary bucket (the access is also
992:           // counted as MISS), so it must NOT be added to TOTAL_ACCESS.
993:           total_access[type] += m_stats.at(streamid)[type][status];
994:       }
995:     }
996:     for (unsigned type = 0; type < NUM_MEM_ACCESS_TYPE; ++type) {
997:       if (total_access[type] > 0)
998:         fprintf(fout, "\t%s[%s][%s] = %u\n", m_cache_name.c_str(),
999:                 mem_access_type_str((enum mem_access_type)type), "TOTAL_ACCESS",
1000:                 total_access[type]);
1001:     }
1002:   }
1003: }
